// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    Reentrancy_bonus c;
    function setUp() public { c = new Reentrancy_bonus(); }

    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));

        Reverter r = new Reverter();

        address target = (uint160(recipient) & 1 == 0) ? address(r) : recipient;

        vm.deal(address(c), 100);

        bool ok;
        try c.getFirstWithdrawalBonus(target) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Reverter {
    receive() external payable {
        if (msg.value == 0) revert();
    }
}
